  1	lemma BinarySearch(intSeq:seq<int>, key:int) returns (r:int)
  2	    // original
  3	    requires forall i,j | 0 <= i <= j < |intSeq| :: intSeq[i] <= (intSeq[j]) + 1
  4	    ensures r >= 0 ==> r < |intSeq| && intSeq[r] == key
  5	    ensures r < 0 ==> forall i:nat | i < |intSeq| :: intSeq[i] != key
  6	{  
  7	    var lo:nat := 0;
  8	    var hi:nat := |intSeq|;
  9	    while lo < hi
 10	    invariant 0 <= lo <= hi <= |intSeq|
 11	    invariant forall i:nat | 0 <= i < lo :: intSeq[i] < key
 12	    invariant forall i:nat | hi <= i < |intSeq| :: intSeq[i] > key
 13	    {
 14	        var mid := (lo + hi) / 2;
 15	        if (intSeq[mid] < key) {
 16	            lo := mid + 1;
 17	        } else if (intSeq[mid] > key) {
 18	            hi := mid;
 19	        } else {
 20	            return mid;
 21	        }
 22	    }
 23	    return -1;
 24	}
